// Pure read of what the scheduler already wrote. No Apple traffic here.
const APP_ID = '6692632196';
const rows = [];

for (const item of $input.all()) {
  const data = item.json.data;
  if (!data || !Array.isArray(data.items)) continue;

  for (const kw of data.items) {
    const position = (kw.positions || []).find((p) => p.appId === APP_ID);
    const current = position?.currentPosition ?? null;
    const previous = position?.previousPosition ?? null;
    rows.push({
      country: kw.country,
      keyword: kw.keyword,
      popularity: kw.popularity,
      difficulty: kw.difficultyScore,
      appCount: kw.appCount,
      rank: current,
      previousRank: previous,
      // Ranks improve downwards, so a negative delta is a gain.
      change: current != null && previous != null ? previous - current : null,
      status: kw.keywordStatus,
      updatedAt: kw.updatedAt,
    });
  }
}

const ranked = rows.filter((r) => r.rank != null);
const movers = ranked
  .filter((r) => r.change != null && r.change !== 0)
  .sort((a, b) => Math.abs(b.change) - Math.abs(a.change))
  .slice(0, 15);

return [
  {
    json: {
      generatedAt: new Date().toISOString(),
      totals: {
        keywords: rows.length,
        ranking: ranked.length,
        failed: rows.filter((r) => r.status === 'failed').length,
        pending: rows.filter((r) => r.status === 'pending').length,
      },
      byCountry: Object.fromEntries(
        [...new Set(rows.map((r) => r.country))].map((c) => [
          c,
          {
            tracked: rows.filter((r) => r.country === c).length,
            ranking: ranked.filter((r) => r.country === c).length,
            best: ranked
              .filter((r) => r.country === c)
              .reduce((min, r) => (min == null || r.rank < min ? r.rank : min), null),
          },
        ])
      ),
      movers,
      rows,
    },
  },
];
